#include <bits/stdc++.h>
using namespace std;

const long long MOD = 1000000007LL;

long long countWays(int m, long long D, const vector<long long>& f) {
    long long dp0 = 1; // dp[0]
    if (m == 0) return dp0;

    long long dp1 = 1; // dp[1]
    for (int i = 1; i < m; ++i) {
        long long cur = dp1;
        if (f[i] - f[i - 1] <= D) {
            cur = (cur + dp0) % MOD;
        }
        dp0 = dp1;
        dp1 = cur;
    }
    return dp1;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int q;
    cin >> q;
    while (q--) {
        int m;
        long long D;
        cin >> m >> D;

        vector<long long> f(m);
        for (int i = 0; i < m; ++i)
            cin >> f[i];

        cout << countWays(m, D, f) << '\n';
    }

    return 0;
}
